package com.atskolla.teacher;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.os.*;
import android.widget.*;
import java.io.*;
import java.util.concurrent.*;
import static com.atskolla.teacher.Ui.*;

/** Native PDF preview and Downloads export. The source survives rotation/process recreation. */
public class PdfPreviewActivity extends Activity {
    private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private File file;private String filename;private PdfRenderer renderer;private ParcelFileDescriptor descriptor;private ImageView image;private TextView pageLabel;private Button download,previous,next;private Bitmap bitmap;private int page;private volatile boolean closed,saving;
    @Override public void onCreate(Bundle state){super.onCreate(state);try{file=InvoiceFiles.resolve(this,getIntent().getStringExtra("document_id"));if(!file.isFile())throw new IOException();}catch(Exception error){finish();return;}filename=getIntent().getStringExtra("filename");if(filename==null)filename="Laporan-Guru.pdf";filename=filename.replaceAll("[^A-Za-z0-9._-]","_");page=state==null?0:state.getInt("page",0);
        LinearLayout root=column(this);root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft()+dp(this,16),insets.getSystemWindowInsetTop()+dp(this,12),insets.getSystemWindowInsetRight()+dp(this,16),insets.getSystemWindowInsetBottom()+dp(this,12));return insets.consumeSystemWindowInsets();});
        LinearLayout header=row(this);header.addView(iconTile(this,"card",Color.WHITE,BLUE,36),new LinearLayout.LayoutParams(dp(this,36),dp(this,36)));String documentTitle=getIntent().getStringExtra("document_title");TextView title=text(this,documentTitle==null?"Preview laporan":documentTitle,18,INK,true);title.setPadding(dp(this,10),0,0,0);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);gap(root,12);
        SoftScrollView scroll=new SoftScrollView(this);image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription("Halaman PDF laporan guru");image.setBackgroundColor(Color.WHITE);scroll.addView(image,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));gap(root,10);
        LinearLayout navigation=row(this);previous=button(this,"‹",false,()->render(page-1));next=button(this,"›",false,()->render(page+1));pageLabel=text(this,"",12,MUTED,false);pageLabel.setGravity(android.view.Gravity.CENTER);navigation.addView(previous,new LinearLayout.LayoutParams(dp(this,48),dp(this,48)));navigation.addView(pageLabel,new LinearLayout.LayoutParams(0,-2,1));navigation.addView(next,new LinearLayout.LayoutParams(dp(this,48),dp(this,48)));root.addView(navigation);gap(root,8);
        download=button(this,"Download PDF",true,this::download);download.setEnabled(false);root.addView(download,new LinearLayout.LayoutParams(-1,dp(this,48)));gap(root,8);root.addView(button(this,"Kembali",false,this::finish),new LinearLayout.LayoutParams(-1,dp(this,48)));setContentView(root);root.requestApplyInsets();
        io.execute(()->{try{descriptor=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);renderer=new PdfRenderer(descriptor);main.post(()->{if(!closed)render(page);});}catch(Exception error){main.post(()->{if(!closed)pageLabel.setText("PDF belum dapat dibuka. Silakan kembali dan coba lagi.");});}});
    }
    private void render(int index){if(renderer==null||closed)return;int target=Math.max(0,Math.min(index,renderer.getPageCount()-1));previous.setEnabled(false);next.setEnabled(false);io.execute(()->{try(PdfRenderer.Page pdf=renderer.openPage(target)){int width=Math.min(960,getResources().getDisplayMetrics().widthPixels);Bitmap rendered=Bitmap.createBitmap(width,Math.min(2048,Math.round(width*(pdf.getHeight()/(float)pdf.getWidth()))),Bitmap.Config.ARGB_8888);rendered.eraseColor(Color.WHITE);pdf.render(rendered,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);int count=renderer.getPageCount();main.post(()->{if(closed){rendered.recycle();return;}image.setImageBitmap(rendered);bitmap=rendered;page=target;pageLabel.setText("Halaman "+(page+1)+" / "+count);previous.setEnabled(page>0);next.setEnabled(page+1<count);download.setEnabled(!saving);});}catch(Exception | OutOfMemoryError error){main.post(()->{if(!closed){pageLabel.setText("Halaman PDF belum dapat ditampilkan. File tetap dapat diunduh.");download.setEnabled(true);}});}});}
    private void download(){if(saving||closed)return;if(Build.VERSION.SDK_INT<29){Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/pdf").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,filename);try{startActivityForResult(save,730);}catch(ActivityNotFoundException error){Toast.makeText(this,"Pemilih berkas belum tersedia pada perangkat ini.",Toast.LENGTH_LONG).show();}return;}saving=true;download.setEnabled(false);io.execute(()->{try{InvoiceFiles.download(this,file,filename);saved(true);}catch(Exception error){saved(false);}});}
    private void saved(boolean success){main.post(()->{saving=false;if(!closed){download.setEnabled(true);Toast.makeText(this,success?"PDF tersimpan di Download/ATSkolla":"PDF belum tersimpan. Silakan coba lagi.",Toast.LENGTH_LONG).show();onDownloadSaved(success);}});}
    protected void onDownloadSaved(boolean success){}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=730||result!=RESULT_OK||data==null||data.getData()==null)return;saving=true;download.setEnabled(false);io.execute(()->{try(InputStream input=new FileInputStream(file);OutputStream output=getContentResolver().openOutputStream(data.getData())){if(output==null)throw new IOException();InvoiceFiles.copy(input,output);saved(true);}catch(Exception error){saved(false);}});}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("page",page);}
    @Override protected void onDestroy(){closed=true;main.removeCallbacksAndMessages(null);if(image!=null)image.setImageDrawable(null);bitmap=null;io.execute(()->{if(renderer!=null)renderer.close();if(descriptor!=null)try{descriptor.close();}catch(IOException ignored){}});io.shutdown();super.onDestroy();}
}
